import {validateGroup, filterGroups, groupScore, buildSearchLinks, csvExport, parseImport, demoGroups, formatNumber, MAX_GROUPS} from './core.js';
import {createFieldworkWorkspace} from './field-ui.js';
import {normalizeSampling,validateSampling} from './sampling.js';
import {validateFieldwork} from './fieldwork.js';
import {userToday,captureFormDraft,watchFormDraft,restoreFormDraft,clearFormDraft,showFormErrors,checkFormValidity} from './usability.js';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(id,cls='')=>`<svg aria-hidden="true" class="${cls}"><use href="#i-${id}"/></svg>`;
const STORAGE='groupscout-v1', RECOVERY='groupscout-recovery-v1';
const DEFAULT_CAMPAIGN={topic:'Tiêu dùng xanh trong ngành bất động sản',formUrl:'',minutes:5,baseline:0};
let groups=[],campaign={...DEFAULT_CAMPAIGN},checks={},sampling=normalizeSampling(),lastExportAt='',postDraft='',demo=demoGroups.map(g=>({...g})),view='discover',mode='demo',storageOk=true,workspace=null,storageRevision=0,staleTab=false,rawReadFailure='';
let loadedRaw='';
try{loadedRaw=localStorage.getItem(STORAGE)||'';if(loadedRaw){const obj=JSON.parse(loadedRaw),parsed=parseImport(loadedRaw,{today:userToday()});if(!parsed.ok)throw new Error('invalid');groups=parsed.groups;campaign=cleanCampaign(obj.campaign);checks=cleanChecks(obj.checks);sampling=normalizeSampling(obj.sampling);lastExportAt=typeof obj.lastExportAt==='string'&&Number.isFinite(Date.parse(obj.lastExportAt))?obj.lastExportAt:'';storageRevision=Number.isSafeInteger(obj.revision)?obj.revision:0;postDraft=typeof obj.postDraft==='string'?obj.postDraft.slice(0,10000):'';mode=groups.length?'mine':'demo';}}
catch(e){storageOk=false;rawReadFailure=loadedRaw||'Không truy cập được bộ nhớ trình duyệt.';queueMicrotask(()=>{updateStorageAlert();toast('Chưa đọc được bản lưu. Hãy xuất dữ liệu thô hoặc nhập bản sao hợp lệ trước khi ghi tiếp.');});}
function cleanCampaign(obj){if(!obj||typeof obj!=='object')return {...DEFAULT_CAMPAIGN};const topic=typeof obj.topic==='string'&&obj.topic.trim()?obj.topic.trim().slice(0,200):DEFAULT_CAMPAIGN.topic;const formUrl=validFormUrl(obj.formUrl)?String(obj.formUrl||''):'';return {topic,formUrl,minutes:Number.isInteger(+obj.minutes)&&+obj.minutes>=1&&+obj.minutes<=120?+obj.minutes:5,baseline:Number.isSafeInteger(+obj.baseline)&&+obj.baseline>=0&&+obj.baseline<=100000?+obj.baseline:0};}
function cleanChecks(obj){const value={};for(const k of ['age','intent','rules','consent','duplicates'])value[k]=obj?.[k]===true;return value;}
function validFormUrl(url){return !url||validateFieldwork({surveyUrl:url}).ok;}
function snapshot(){return {version:2,groups,campaign,sampling,checks,postDraft,lastExportAt,revision:storageRevision};}
function updateStorageAlert(){const alert=$('storage-alert');alert.hidden=!(staleTab||rawReadFailure);$('storage-alert-text').textContent=rawReadFailure?'Bản lưu hiện tại chưa đọc được. App đang giữ nguyên, chưa ghi đè. Xuất dữ liệu thô để dự phòng hoặc vào Kế hoạch để nhập bản sao.':'Dữ liệu đã thay đổi ở tab khác. Tải lại để tiếp tục với bản mới; có thể xuất JSON trước nếu cần giữ nội dung đang sửa.';$('storage-reload').textContent=rawReadFailure?'Xuất dữ liệu thô':'Tải lại dữ liệu';}
function persist(){
 if(rawReadFailure||staleTab){updateStorageAlert();toast('Chưa ghi dữ liệu: hãy xử lý thông báo ở đầu trang để tránh mất bản lưu.');return false;}
 try{const current=localStorage.getItem(STORAGE),revision=current?(JSON.parse(current).revision||0):0;if(revision!==storageRevision){staleTab=true;updateStorageAlert();toast('Tab khác đã sửa dữ liệu. Hãy tải lại trước khi lưu.');return false;}const next=snapshot();next.revision=storageRevision+1;localStorage.setItem(STORAGE,JSON.stringify(next));storageRevision=next.revision;storageOk=true;}
 catch{storageOk=false;toast('Trình duyệt không lưu được. Hãy xuất JSON để giữ dữ liệu.');}
 document.querySelector('.storage-state').innerHTML=`<span></span>${storageOk?'Lưu trên trình duyệt này':'Chưa lưu được · cần xuất JSON'}`;document.querySelector('.local-note').innerHTML=`<span></span>${storageOk?'Dữ liệu đã lưu':'Chưa lưu được'}`;return storageOk;
}
function saveGroup(input){const result=validateGroup(input,{today:userToday()});if(!result.ok)return result;const value=result.value;if(groups.some(g=>g.id!==value.id&&g.url.toLowerCase()===value.url.toLowerCase()))result.errors.push('Nhóm này đã có trong danh sách.');if(groups.some(g=>g.id!==value.id&&g.sourceCode===value.sourceCode))result.errors.push('Mã nguồn đã dùng ở nhóm khác. Hãy đặt mã riêng.');if(!groups.some(g=>g.id===value.id)&&groups.length>=MAX_GROUPS)result.errors.push(`Danh sách tối đa ${MAX_GROUPS} nhóm.`);if(result.errors.length)return {...result,ok:false};const before=groups;groups=groups.some(g=>g.id===value.id)?groups.map(g=>g.id===value.id?value:g):[...groups,value];if(!persist()){groups=before;return {ok:false,errors:['Chưa lưu được. Hãy kiểm tra thông báo lưu trữ, rồi xuất bản sao nếu cần.']};}render();return {ok:true,value,errors:[]};}
function retainRecovery(){try{localStorage.setItem(RECOVERY,JSON.stringify({savedAt:new Date().toISOString(),data:snapshot()}));$('export-recovery').hidden=false;return true;}catch{toast('Chưa tạo được bản khôi phục. Hãy xuất JSON trước khi xóa hoặc nhập bản sao.');return false;}}
window.addEventListener('storage',e=>{if(e.key===STORAGE||e.key===null){staleTab=true;updateStorageAlert();}});
$('storage-reload').onclick=()=>{if(rawReadFailure)download('groupscout-unreadable-backup.txt',rawReadFailure,'text/plain;charset=utf-8');else location.reload();};
let toastTimer;function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4300);}
function dateText(str){return str?new Date(`${str}T00:00:00`).toLocaleDateString('vi-VN'):'Chưa có ngày kiểm tra';}
function totalResponses(){return campaign.baseline+groups.reduce((sum,g)=>sum+g.responses,0);}
function setView(next){view=next;if(['saved','fieldwork','plan'].includes(next))mode='mine';const names={discover:'Khám phá nhóm',saved:'Nhóm đã lưu',plan:'Kế hoạch 500 mẫu',fieldwork:'Bàn thu thập'};document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===view;el.classList.toggle('active',active);if(el.getAttribute('role')==='tab')el.setAttribute('aria-selected',String(active));});$('breadcrumb-current').textContent=names[view];$('discovery-panel').hidden=!['discover','saved'].includes(view);$('plan-panel').hidden=view!=='plan';$('fieldwork-panel').hidden=view!=='fieldwork';$('page-title').innerHTML=view==='fieldwork'?'Đi từng bước,<br>đủ mẫu phù hợp<span>.</span>':view==='plan'?'Từng phản hồi,<br>gần hơn mục tiêu<span>.</span>':view==='saved'?'Chọn đúng nhóm,<br>tập trung kết nối<span>.</span>':'Tìm cộng đồng,<br>chạm đúng người<span>.</span>';$('page-subtitle').textContent=view==='fieldwork'?'Theo dõi xin phép, lịch việc và chất lượng phản hồi trong một nơi.':view==='plan'?'Chuẩn bị khảo sát và theo dõi 500 phản hồi hợp lệ.':view==='saved'?'Danh sách ưu tiên để tuyển người tham gia khảo sát.':'Từ những nhóm phù hợp đến 500 phản hồi có giá trị.';render();}
function render(){workspace?.render();document.querySelector('.stats-grid').hidden=view==='fieldwork'&&!groups.length&&totalResponses()===0;const data=mode==='demo'?demo:groups;const responses=totalResponses(),saved=groups.filter(g=>g.saved).length;$('stat-total').textContent=formatNumber(data.length);$('stat-total-sub').textContent=mode==='demo'?'Ví dụ minh họa · chưa xác minh':'Dữ liệu bạn đã thêm';$('stat-anon').textContent=formatNumber(data.filter(g=>g.anonymous==='yes').length);$('stat-anon').nextElementSibling.textContent=mode==='demo'?'Ví dụ minh họa · chưa xác minh':'Đã đánh dấu xác minh';$('stat-saved').textContent=formatNumber(saved);$('nav-saved').textContent=saved;$('tab-saved').textContent=saved;$('stat-responses').textContent=formatNumber(responses);$('progress-label').textContent=responses>=500?'Đã đạt mục tiêu 500 mẫu':`Còn ${formatNumber(500-responses)} mẫu để đạt mục tiêu`;$('progress-ring').style.setProperty('--progress',`${Math.min(100,responses/5)}%`);$('mode-mine').classList.toggle('active',mode==='mine');$('mode-demo').classList.toggle('active',mode==='demo');$('mode-mine').setAttribute('aria-pressed',String(mode==='mine'));$('mode-demo').setAttribute('aria-pressed',String(mode==='demo'));$('demo-notice').hidden=mode!=='demo';$('directory-title').innerHTML=`${view==='saved'?'Nhóm ưu tiên':'Cộng đồng tiềm năng'} <span id="result-count"></span>`;$('directory-description').textContent=mode==='demo'?'Thử bộ lọc với các ví dụ giả lập trước khi thêm nhóm thật.':'Thông tin nhóm do bạn nhập và xác minh, chưa được Facebook đồng bộ.';
const options={query:$('directory-query').value,minMembers:+$('min-members').value,minPosts:+$('min-posts').value,anonymousOnly:$('anon-filter').checked,surveysOnly:$('survey-filter').checked,location:$('directory-location').value,savedOnly:view==='saved',sort:$('sort-select').value};const filtered=filterGroups(data,options);$('result-count').textContent=filtered.length;$('results-summary').textContent=`Hiển thị ${filtered.length} / ${data.length} nhóm${mode==='demo'?' minh họa':''}`;$('group-grid').innerHTML=filtered.map(card).join('');$('empty-state').hidden=filtered.length>0;$('group-grid').hidden=filtered.length===0;
if(!filtered.length){const isBlank=mode==='mine'&&!groups.length;$('empty-title').textContent=isBlank?'Bắt đầu danh sách nhóm của bạn':view==='saved'?'Chưa có nhóm đã lưu phù hợp':'Chưa có nhóm khớp bộ lọc';$('empty-text').textContent=isBlank?'Tìm nhóm trên Facebook, kiểm tra số thành viên và quyền đăng, rồi thêm vào đây.':'Thử đặt lại bộ lọc hoặc thêm nhóm đã xác minh. Việc tìm trên Facebook mở trong tab mới.';$('empty-add').textContent=isBlank?'Thêm nhóm đầu tiên':'Thêm nhóm đã kiểm tra';}}
function permissionBadge(type,value){const labels=type==='anonymous'?{yes:'Có đăng ẩn danh',no:'Không đăng ẩn danh',unknown:'Ẩn danh: chưa rõ'}:{yes:'Cho khảo sát',no:'Không cho khảo sát',unknown:'Khảo sát: chưa rõ'};return `<span class="badge ${value}">${icon(value==='yes'?'check':value==='no'?'close':'info')}${labels[value]}</span>`;}
function card(g,i){const name=g.name.replace(/^\[Minh họa\]\s*/,''),n=i%6;return `<article class="group-card"><div class="card-top"><div class="group-avatar tone${n}">${icon(g.category==='Sống xanh'?'leaf':g.category==='Cư dân'?'users':'grid')}</div><div class="card-top-meta"><span class="card-category">${esc(g.category||'Chưa phân loại')}</span><span class="card-location">${icon('location')}${esc(g.location||'Chưa rõ khu vực')}</span></div><button class="save-button ${g.saved?'saved':''}" data-save="${esc(g.id)}" title="${g.saved?'Bỏ lưu nhóm':'Lưu nhóm'}" aria-label="${g.saved?'Bỏ lưu':'Lưu'} ${esc(name)}" aria-pressed="${g.saved}">${icon('bookmark')}</button></div><h3 class="card-name">${esc(name)}</h3><div class="card-metrics"><div><strong>${formatNumber(g.members)}</strong><span>${icon('users')}thành viên</span></div><div><strong>${formatNumber(g.postsPerDay)}${g.postsPerDay!==null?'<small> bài / ngày</small>':''}</strong><span>${icon('activity')}hoạt động quan sát</span></div></div><div class="card-permissions">${permissionBadge('anonymous',g.anonymous)}${permissionBadge('surveys',g.surveys)}</div><div class="card-foot"><span title="Quy mô tối đa 30 + hoạt động tối đa 30 + ẩn danh 20 + cho khảo sát 20. Không đo độ phù hợp của người trả lời.">${icon('activity')}Ưu tiên ${groupScore(g)}/100${g._demo?' · Ví dụ':''}</span><button data-details="${esc(g.id)}">${g._demo?'Xem ví dụ':'Xem thông tin'}${icon('arrow')}</button></div></article>`;}
function setMode(next){mode=next;render();}
function openSearch(provider){let query=$('search-input').value.trim()||'mua nhà căn hộ';const location=$('search-location').value||'TP.HCM Hà Nội';const url=buildSearchLinks({query,location})[provider];window.open(url,'_blank','noopener,noreferrer');toast('Mở tìm kiếm ở tab mới. Thêm nhóm vào app sau khi kiểm tra.');}
function resetFilters(){$('directory-query').value='';$('directory-location').value='';$('min-members').value='0';$('min-posts').value='0';$('anon-filter').checked=false;$('survey-filter').checked=false;render();}
function openGroup(group=null){const form=$('group-form');form.reset();$('group-errors').textContent='';form.querySelectorAll('[data-inline-error]').forEach(el=>el.remove());form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));$('group-extra').open=false;$('group-dialog-title').textContent=group?'Thông tin nhóm':'Thêm nhóm Facebook';form.elements.id.value=group?.id||'';if(group){for(const [key,value]of Object.entries(group)){const input=form.elements.namedItem(key);if(!input)continue;if(input.type==='checkbox')input.checked=!!value;else{if(input.tagName==='SELECT'&&value&&!Array.from(input.options).some(o=>o.value===value))input.add(new Option(value,value));input.value=value??'';}}}else{form.elements.verifiedAt.value='';form.elements.location.value='';form.elements.category.value='';form.elements.saved.checked=true;}restoreFormDraft(form,`group:${group?.id||'new'}`);$('delete-group').hidden=!group;$('group-dialog').showModal();}
function showInfo(title,html){$('info-title').textContent=title;$('info-content').innerHTML=html;$('info-dialog').showModal();}
function details(id){const g=(mode==='demo'?demo:groups).find(g=>g.id===id);if(!g)return;showInfo(g._demo?'Nhóm minh họa':'Thông tin đã ghi nhận',`${g._demo?'<div class="demo-notice"><span>Đây là ví dụ giả lập, không phải một nhóm Facebook đã được tìm thấy.</span></div>':''}<h3>${esc(g.name)}</h3><p>${esc(g.category)} · ${esc(g.location)}</p><div class="detail-grid"><div><strong>${formatNumber(g.members)}</strong><span>Thành viên</span></div><div><strong>${formatNumber(g.postsPerDay)}</strong><span>Bài đăng trung bình / ngày</span></div><div><strong>${groupScore(g)}/100</strong><span>Điểm ưu tiên theo tiêu chí</span></div><div><strong>${formatNumber(g.responses)}</strong><span>Phản hồi hợp lệ đã nhập</span></div></div><p>${permissionBadge('anonymous',g.anonymous)} ${permissionBadge('surveys',g.surveys)}</p><p><strong>Ngày kiểm tra:</strong> ${dateText(g.verifiedAt)}</p><h3>Ghi chú & nguồn xác minh</h3><p style="white-space:pre-wrap">${esc(g.notes||'Chưa ghi nhận nguồn xác minh.')}</p><h3>Cách tính điểm</h3><p>Quy mô nhóm tối đa 30 điểm, mức hoạt động tối đa 30 điểm (3 điểm cho mỗi bài/ngày), có đăng ẩn danh 20 điểm và cho khảo sát 20 điểm. Số thành viên từ 1 / 1.000 / 10.000 / 30.000 / 100.000 tương ứng 4 / 10 / 18 / 24 / 30 điểm. Thông tin chưa rõ được 0 điểm.</p><p>Điểm dùng để sắp xếp danh sách, không ước tính số mẫu hoặc mức độ phù hợp. Quyền đăng và hoạt động có thể thay đổi; hãy kiểm tra lại trước khi đăng.</p>${g._demo?'':`<p><a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">Mở nhóm Facebook ↗</a></p><button class="button primary" id="detail-edit">${icon('edit')}Chỉnh sửa thông tin</button>`}`);if(!g._demo){$('info-content').insertAdjacentHTML('beforeend',`<div class="detail-field-actions"><button class="button secondary" id="detail-workflow">${icon('clock')}Theo dõi tuyển mẫu</button><button class="button secondary" id="detail-compose">${icon('edit')}Soạn cho nhóm</button></div>`);$('detail-workflow').onclick=()=>{$('info-dialog').close();workspace.openWorkflow(g.id);};$('detail-compose').onclick=()=>{$('info-dialog').close();workspace.openComposer(g.id);};}$('detail-edit')?.addEventListener('click',()=>{$('info-dialog').close();openGroup(g);});}
function confirmAction(title,message,action){$('confirm-title').textContent=title;$('confirm-text').textContent=message;$('confirm-action').onclick=()=>{$('confirm-dialog').close();action();};$('confirm-dialog').showModal();}
function syncCampaignForm(){const form=$('campaign-form');for(const [key,value]of Object.entries(campaign))form.elements.namedItem(key).value=value;document.querySelectorAll('[data-check]').forEach(el=>el.checked=checks[el.dataset.check]===true);$('post-template').value=postDraft||generatePost();}
function generatePost(){return `Chào mọi người, mình đang thực hiện khảo sát về “${campaign.topic}”.\n\nMình mong nhận được chia sẻ từ các bạn 18–65 tuổi, đang sinh sống tại TP.HCM hoặc Hà Nội và có ý định mua nhà. Bảng hỏi dự kiến mất khoảng ${campaign.minutes} phút.\n\nViệc tham gia hoàn toàn tự nguyện. Mục đích nghiên cứu và cách sử dụng dữ liệu được trình bày trong phần giới thiệu của biểu mẫu; bạn vui lòng đọc trước khi trả lời.\n\nLink khảo sát: ${campaign.formUrl||'[Dán link Google Form tại đây]'}\n\nCảm ơn mọi người đã dành thời gian! Mình xin phép quản trị viên chia sẻ khảo sát và sẽ tuân thủ nội quy của nhóm.`;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJson(){if(rawReadFailure){download('groupscout-unreadable-backup.txt',rawReadFailure,'text/plain;charset=utf-8');toast('Đã xuất nguyên dữ liệu thô; chưa ghi đè bản lưu.');return;}const previous=lastExportAt;lastExportAt=new Date().toISOString();download('groupscout-backup.json',JSON.stringify({...snapshot(),exportedAt:lastExportAt},null,2),'application/json;charset=utf-8');if(!persist())lastExportAt=previous;workspace?.render();toast('Đã tạo bản tải xuống JSON. Hãy giữ tệp để khôi phục hoặc chuyển thiết bị.');}
function guide(){showInfo('Bắt đầu với GroupScout',`<h3>1. Tìm cộng đồng phù hợp</h3><p>Chọn từ khóa như “mua nhà lần đầu”, “căn hộ xanh” hoặc “cộng đồng cư dân”, cùng khu vực Hà Nội / TP.HCM. Nút tìm kiếm mở Facebook hoặc Google trong tab mới.</p><h3>2. Xác minh rồi thêm nhóm</h3><p>Vào nhóm, ghi số thành viên và số bài gần đây. Quan sát một khoảng thời gian nhất quán, chẳng hạn 7 ngày, rồi chia số bài cho 7. Kiểm tra lựa chọn đăng ẩn danh và nội quy về đăng khảo sát. Nếu chưa rõ, giữ trạng thái “Chưa xác minh”.</p><h3>3. Lưu danh sách ưu tiên</h3><p>Dùng bộ lọc theo quy mô, mức hoạt động và quyền đăng. Bấm biểu tượng đánh dấu để lưu nhóm. Điểm ưu tiên chỉ là quy tắc sắp xếp, không dự báo số người sẽ trả lời.</p><h3>4. Theo dõi 500 mẫu hợp lệ</h3><p>Trong Kế hoạch 500 mẫu, thêm Google Form và sao chép bài mời. Sau khi tự đăng trên Facebook, nhập số phản hồi hợp lệ ở từng nhóm. Sàng lọc tuổi 18–65, nơi ở và ý định mua nhà; không cộng trùng.</p><div class="mini-note">Dữ liệu lưu trong trình duyệt hiện tại. Hãy xuất JSON thường xuyên để dự phòng. App không tự đăng bài, đọc tài khoản Facebook hay nhận phản hồi từ Google Form.</div>`);}
function limitations(){showInfo('Nguồn dữ liệu & giới hạn',`<h3>Dữ liệu nhóm do bạn xác minh</h3><p>App tạo liên kết tìm kiếm công khai và quản lý thông tin bạn nhập. App chưa kết nối trực tiếp Facebook; không tự xác nhận số thành viên, hoạt động, độ tuổi, ý định mua nhà hay quyền đăng ẩn danh. Dữ liệu minh họa được tạo giả lập và không đưa vào bản xuất.</p><h3>Vì sao cần kiểm tra trực tiếp?</h3><p>Facebook đã gỡ Groups API vào tháng 4/2024. Việc tham gia ẩn danh còn phụ thuộc thiết lập của nhóm và khả năng sử dụng của tài khoản. Bật ẩn danh không có nghĩa nhóm cho phép đăng link khảo sát.</p><p>Đăng ẩn danh không che danh tính của bạn với quản trị viên, người kiểm duyệt và Meta. Hãy kiểm tra thông báo của Facebook khi đăng.</p><h3>Nguồn tham khảo</h3><ul><li><a target="_blank" rel="noopener noreferrer" href="https://developers.facebook.com/docs/graph-api/changelog/version19.0">Meta · Graph API v19.0 changelog</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://about.fb.com/news/2025/11/facebook-update-group-admins-flexibility-protecting-member-privacy/">Meta · Thiết lập tham gia ẩn danh trong nhóm</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.facebook.com/help/832270967369626/">Facebook Help · Participate anonymously</a></li></ul><h3>Dữ liệu khảo sát</h3><p>Tiến độ là tổng phản hồi bạn nhập thủ công, không phải số đã được app kiểm chứng. App không nhận dữ liệu Google Form. Không nhập thông tin cá nhân của người tham gia vào ghi chú nhóm.</p>`);}
document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>setView(el.dataset.view)));
document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>$(el.dataset.close).close()));
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('mode-mine').onclick=()=>setMode('mine');$('mode-demo').onclick=()=>setMode('demo');$('directory-query').addEventListener('input',render);$('search-input').addEventListener('keydown',e=>{if(e.key==='Enter')openSearch('facebook');});for(const id of ['directory-location','min-members','min-posts','anon-filter','survey-filter','sort-select'])$(id).addEventListener('change',render);
$('search-facebook').onclick=()=>openSearch('facebook');$('search-google').onclick=()=>openSearch('google');document.querySelectorAll('[data-keyword]').forEach(el=>el.onclick=()=>{$('search-input').value=el.dataset.keyword;openSearch('facebook');});$('reset-filters').onclick=resetFilters;
$('add-btn').onclick=()=>openGroup();$('empty-add').onclick=()=>openGroup();$('guide-btn').onclick=guide;$('limitations-btn').onclick=limitations;
$('group-grid').addEventListener('click',e=>{const save=e.target.closest('[data-save]'),detail=e.target.closest('[data-details]');if(save){const group=(mode==='demo'?demo:groups).find(g=>g.id===save.dataset.save);if(!group)return;if(mode==='mine'){if(!saveGroup({...group,saved:!group.saved}).ok)return;}else group.saved=!group.saved;toast(group._demo?`Ví dụ ${group.saved?'đã lưu':'đã bỏ lưu'} trong phiên minh họa.`:group.saved?'Đã bỏ lưu nhóm.':'Đã lưu nhóm vào danh sách ưu tiên.');render();}if(detail)details(detail.dataset.details);});
watchFormDraft($('group-form'),'group-draft-note');$('group-form').noValidate=true;
$('group-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!checkFormValidity(form))return;const input=Object.fromEntries(new FormData(form)),old=groups.find(g=>g.id===input.id);input.id=input.id||`g-${crypto.randomUUID()}`;input.saved=form.elements.saved.checked;const result=saveGroup({...old,...input});if(!result.ok){showFormErrors(form,$('group-errors'),result.errors);return;}clearFormDraft(form);mode='mine';resetFilters();$('group-dialog').close();setView('fieldwork');toast(old?'Đã lưu thông tin nhóm.':'Đã thêm nhóm. Chọn “Cập nhật mẫu” khi có phản hồi.');});
$('discard-group-draft').onclick=()=>{const form=$('group-form'),group=groups.find(g=>g.id===form.elements.id.value);clearFormDraft(form,{discardAll:true});$('group-dialog').close();openGroup(group);toast('Đã bỏ bản nháp, thông tin đã lưu vẫn giữ nguyên.');};
for(const key of ['anonymous','surveys'])$('group-form').elements.namedItem(key).addEventListener('change',()=>{const f=$('group-form');if(f.elements.namedItem(key).value==='yes'&&!f.elements.verifiedAt.value){f.elements.verifiedAt.value=userToday();captureFormDraft(f);}});
$('delete-group').onclick=()=>{const id=$('group-form').elements.id.value,g=groups.find(g=>g.id===id);if(!g)return;$('group-dialog').close();confirmAction('Xóa nhóm khỏi danh sách?',`Xóa “${g.name}” và ${g.responses} phản hồi được ghi nhận? Nếu chỉ ngừng tuyển, dùng Tạm dừng trong Bàn thu thập để giữ số mẫu. App sẽ giữ một bản khôi phục trước khi xóa.`,()=>{if(!retainRecovery())return;const before=groups;groups=groups.filter(g=>g.id!==id);if(!persist()){groups=before;return;}render();toast('Đã xóa nhóm. Bản trước khi xóa có trong Kế hoạch → Khôi phục.');});};
$('campaign-form').onsubmit=e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.currentTarget));if(!validFormUrl(obj.formUrl)){toast('Vui lòng dùng link Google Form HTTPS thuộc forms.gle hoặc docs.google.com/forms.');return;}const before=campaign;campaign=cleanCampaign(obj);if(!persist()){campaign=before;return;}if(!postDraft)$('post-template').value=generatePost();render();toast('Đã lưu thiết lập. Dùng “Tạo lại từ thiết lập” để cập nhật bài mời.');};
document.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{checks[el.dataset.check]=el.checked;persist();});
$('post-template').addEventListener('input',e=>{postDraft=e.target.value.slice(0,10000);persist();});$('regenerate-post').onclick=()=>{const regenerate=()=>{postDraft=generatePost();$('post-template').value=postDraft;persist();toast('Đã tạo lại bài mời từ thiết lập đã lưu.');};if(postDraft)confirmAction('Tạo lại bài mời?','Bài mời đang chỉnh sửa sẽ được thay bằng nội dung tạo từ thiết lập đã lưu.',regenerate);else regenerate();};
$('copy-post').onclick=async()=>{if($('post-template').value.includes('[Dán link Google Form tại đây]')){toast('Hãy thêm link khảo sát trước khi sao chép bài mời.');$('campaign-form').elements.formUrl.focus();return;}try{await navigator.clipboard.writeText($('post-template').value);toast('Đã sao chép bài mời khảo sát.');}catch{$('post-template').focus();$('post-template').select();toast('Hãy dùng Ctrl+C hoặc chọn Sao chép để lấy nội dung.');}};
$('export-btn').onclick=exportJson;$('export-json').onclick=exportJson;$('export-csv').onclick=()=>{download('groupscout-groups.csv',csvExport(groups),'text/csv;charset=utf-8');toast('Đã xuất danh sách thật và hồ sơ tuyển mẫu sang CSV.');};$('import-btn').onclick=()=>$('import-file').click();
$('export-recovery').onclick=()=>{try{const recovery=JSON.parse(localStorage.getItem(RECOVERY));if(recovery?.data)download('groupscout-before-change.json',JSON.stringify(recovery.data,null,2),'application/json;charset=utf-8');else if(typeof recovery?.raw==='string')download('groupscout-before-recovery.txt',recovery.raw,'text/plain;charset=utf-8');else toast('Chưa có bản khôi phục.');}catch{toast('Chưa đọc được bản khôi phục.');}};
$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('Tệp phải nhỏ hơn 5 MB.');const text=await file.text(),result=parseImport(text,{today:userToday()});if(!result.ok)throw new Error(result.errors.slice(0,4).join('\n'));const obj=JSON.parse(text);let importedSampling=normalizeSampling();if(!Array.isArray(obj)&&obj.sampling!==undefined){const check=validateSampling(obj.sampling,Number.MAX_SAFE_INTEGER);if(!check.ok)throw new Error(check.errors.join('\n'));importedSampling=check.value;}confirmAction('Khôi phục bản sao?',`Thay ${groups.length} nhóm hiện tại bằng ${result.groups.length} nhóm trong bản sao? Bản hiện tại được giữ trong mục Khôi phục trước khi thay. Các phân bổ vượt tổng sau khi sửa nguồn sẽ được giữ và cảnh báo để bạn đối chiếu.`,()=>{if(staleTab){toast('Tab khác đã thay dữ liệu. Hãy tải lại trước khi nhập.');return;}if(rawReadFailure){try{localStorage.setItem(RECOVERY,JSON.stringify({savedAt:new Date().toISOString(),raw:rawReadFailure}));$('export-recovery').hidden=false;}catch{toast('Hãy xuất dữ liệu thô trước khi khôi phục.');return;}}else if(!retainRecovery())return;const before={...snapshot()},oldFailure=rawReadFailure;groups=result.groups;if(!Array.isArray(obj)){campaign=cleanCampaign(obj.campaign);checks=cleanChecks(obj.checks);postDraft=typeof obj.postDraft==='string'?obj.postDraft.slice(0,10000):'';lastExportAt=typeof obj.lastExportAt==='string'&&Number.isFinite(Date.parse(obj.lastExportAt))?obj.lastExportAt:'';}sampling=importedSampling;rawReadFailure='';if(oldFailure){try{const current=JSON.parse(localStorage.getItem(STORAGE)||'null');storageRevision=Number.isSafeInteger(current?.revision)?current.revision:0;}catch{storageRevision=0;localStorage.removeItem(STORAGE);}}if(!persist()){groups=before.groups;campaign=before.campaign;sampling=before.sampling;checks=before.checks;postDraft=before.postDraft;lastExportAt=before.lastExportAt;rawReadFailure=oldFailure;return;}mode='mine';updateStorageAlert();syncCampaignForm();resetFilters();render();toast('Đã khôi phục. Dữ liệu cũ có bản dự phòng trong Kế hoạch.');});}catch(error){showInfo('Chưa thể nhập dữ liệu',`<p style="white-space:pre-wrap">${esc(error.message)}</p><p>Danh sách hiện tại chưa thay đổi. Chỉ hỗ trợ bản sao JSON có danh sách nhóm hợp lệ.</p>`);}finally{e.target.value='';}};
workspace=createFieldworkWorkspace({getState:()=>({groups,campaign,sampling,lastExportAt}),saveGroup,setSampling(value){const old=sampling;sampling=value;if(!persist()){sampling=old;return false;}render();return true;},openGroup,showInfo,confirmAction,toast,changeView:setView,exportJson});
try{$('export-recovery').hidden=!localStorage.getItem(RECOVERY);}catch{}
syncCampaignForm();setView('fieldwork');updateStorageAlert();
